sysevent_script_action.script:
var recievedDetails = event.parm1;
var bulkDetails = JSON.parse(recievedDetails);
var taskIdStr = event.parm2;
var taskIdArray = taskIdStr.split(',');

var bulkid = bulkDetails.bulkid;
var assignmentgroup = bulkDetails.assignmentgroup;
var assignedto = bulkDetails.assignedto;
var outcome = bulkDetails.outcome;
var advice = bulkDetails.advice;
var reasoncode = bulkDetails.reasoncode;
var reasondesc = bulkDetails.reasondesc;
var suspend = bulkDetails.suspend;
var cancelby = bulkDetails.cancelby;
var setttype = bulkDetails.setttype;
var bktobkinfo = bulkDetails.bktobkinfo;
var cancreference = bulkDetails.cancreference;
var cancelcharge = bulkDetails.cancelcharge;
//adding as part of 4901
var settDate = bulkDetails.settDate;
var fxrTD = bulkDetails.fxrTD;
var valDate = bulkDetails.valDate;

// MSSCUSTODY-6379
var comments = bulkDetails.comments;

//MSSCUSTODY-6087
var fxcx = bulkDetails.fxcx;
var gdi = bulkDetails.gdi;

//MSSCUSTODY-7266
var subOutcome = bulkDetails.subOutcome;
var transRef = bulkDetails.transRef;
var transType = bulkDetails.transType;
var legStatus = bulkDetails.legStatus;
var switchRef = bulkDetails.switchRef;
var counterpartyCode = bulkDetails.counterpartyCode;

//handling bulk upload 

var getUploadType = new GlideRecord("x_hsb11_hsbc_mss_o_hsbc_bulk_transaction");
getUploadType.get(bulkid);
var uploadType = getUploadType.upload_type;

//handling bulk upload 

try {
    for (var i = 0; i < taskIdArray.length; i++) {

        var grTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
        grTask.get(taskIdArray[i]);

        if (outcome == 'Review and closed the task') { // MSSCUSTODY-3964 - Cancelling associated flow if outcome is review and close the task for manual.
            grTask.state = '3'; //closing related maker task
            grTask.assignment_group = assignmentgroup; //Populating assignment group
            grTask.assigned_to = assignedto; //Populating assigned to
            grTask.outcome = outcome;
            grTask.lock = false; //MSSCUSTODY-3993
            grTask.update();
            var grCusCase = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_case");
            grCusCase.addEncodedQuery('sys_id=' + grTask.trade_case_id + '^bulk_id=' + bulkid);
            grCusCase.query();
            if (grCusCase.next()) {
                grCusCase.state = '3';
                grCusCase.update();
            }

            new x_hsb11_mss_c_proc.MSSCustodyBulkUtils().cancelFlow(grTask.trade_case_id, 'Cancelling flow as state is Review and Close');
            grTask.work_notes = 'Cancelling flow as state is Review and Close'; // Updating work notes of Task
        } else {
            grTask.assignment_group = assignmentgroup; //Populating assignment group
            grTask.assigned_to = assignedto; //Populating assigned to
            grTask.outcome = outcome;
            grTask.advice = advice;
            if ((uploadType == '') || (uploadType == 'bulk_level')) {
                grTask.reason_code = reasoncode;
                grTask.reason_description = reasondesc;
				grTask.cancellation_reference = cancreference;
            }
            grTask.suspend = suspend;
            grTask.cancel_by = cancelby; // for outcome 'Process Trade Cancellation'
            grTask.settlement_type = setttype; // for outcome 'Settle Trade'
            grTask.bk_to_bk_info = bktobkinfo;
            grTask.collect_cancel_charge = cancelcharge;
            grTask.state = '3'; //closing related maker task
            grTask.lock = false; //MSSCUSTODY-3993

            // MSSCUSTODY-6379
            grTask.work_notes = comments;

            //added as part of 4901
            if ((grTask.trade_id.contract_type == 'C') && (outcome == 'Confirm Trade')) {
                grTask.value_date = valDate;
            } else if ((grTask.trade_id.contract_type != 'C') && (outcome == 'Confirm Trade')) {
                grTask.value_date = "";
            } else if ((grTask.trade_id.owning_business == 'GC HK') && (outcome == 'Settle Trade')) { //MSSCUSTODY-7754
                grTask.value_date = valDate;
            } else if ((grTask.trade_id.contract_type == 'A') && (outcome == 'Settle Trade')) {
                grTask.value_date = valDate;
            } else if ((grTask.trade_id.contract_type != 'A') && (outcome == 'Settle Trade')) {
                grTask.value_date = "";
            } else if (((grTask.trade_id.fx_location == 'L') || (grTask.trade_id.fx_location == 'O')) && (outcome == 'Process Trade Cancellation')) {
                grTask.fxr_td = fxrTD;
            } else if ((grTask.trade_id.fx_location != 'L') && (grTask.trade_id.fx_location != 'O') && (outcome == 'Process Trade Cancellation')) {
                grTask.fxr_td = "";
            }
            grTask.settlement_date = settDate;

            //MSSCUSTODY-6087
            grTask.fx_cx = fxcx;
            grTask.gdi_indicator = gdi;

            //MSSCUSTODY-7266
            grTask.bulk_id.sub_outcome = subOutcome;
            grTask.bulk_id.transaction_reference = transRef;
            grTask.bulk_id.transaction_type_display = transType;
            grTask.bulk_id.legacy_status_display = legStatus;
            grTask.bulk_id.pair_switch_reference = switchRef;
            grTask.bulk_id.switch_counterparty_code = counterpartyCode;


            grTask.update();
        }
    }
} catch {
    gs.info('Error while updating bulk maker tasks : ' + ex.message);
}
